-- Equity One V5.19
create table if not exists public.bank_imports(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id uuid not null references public.financial_accounts(id) on delete cascade,file_name text not null,file_type text not null,status text not null default 'PENDING',total_rows integer not null default 0,imported_rows integer not null default 0,duplicate_rows integer not null default 0,ignored_rows integer not null default 0,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.bank_import_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,import_id uuid not null references public.bank_imports(id) on delete cascade,account_id uuid not null references public.financial_accounts(id) on delete cascade,external_id text,fingerprint text not null,occurred_on date not null,description text not null,merchant text,amount numeric(14,2) not null check(amount<>0),transaction_type text not null,suggested_category text,final_category text,reconciliation_status text not null default 'PENDING',matched_transaction_id uuid references public.transactions(id) on delete set null,created_transaction_id uuid references public.transactions(id) on delete set null,raw_data jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(user_id,account_id,fingerprint));
create table if not exists public.merchant_rules(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product text not null default 'PERSONAL',merchant_key text not null,merchant_label text,category text not null,use_count integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,product,merchant_key));
alter table public.bank_imports enable row level security;alter table public.bank_import_items enable row level security;alter table public.merchant_rules enable row level security;
